    7: { sharp: "Thank you. Somebody gets it.", dry: "Thank you.", loud: "THANK you! Somebody GETS it!", soft: "Thank you. Somebody gets it.", odd: "Thank you. An egg ally." },
    8: { sharp: "Nobody in that kitchen was fighting about eggs. Everybody's tired, scared of the vote, and the eggs were just there.", dry: "It wasn't really about the eggs. Everybody's tired, and everybody's scared of the vote.",
      loud: "NOBODY in that kitchen was really fighting about EGGS! Everybody's tired, everybody's scared, and the eggs were just THERE!", soft: "Nobody in that kitchen was really fighting about eggs. Everybody's tired, everybody's scared of the vote, and the eggs were just there.",
      odd: "Nobody was really fighting about eggs. Everybody's tired and scared, and the eggs were just in the wrong place." },
